import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _polygon_to_bbox(polygon: Any) -> Optional[Dict[str, float]]:
    if not polygon:
        return None

    xs = []
    ys = []
    for p in polygon:
        if isinstance(p, dict):
            x = p.get("x")
            y = p.get("y")
        else:
            x = getattr(p, "x", None)
            y = getattr(p, "y", None)
        if x is not None and y is not None:
            xs.append(float(x))
            ys.append(float(y))

    if not xs or not ys:
        return None

    return {
        "x_min": min(xs),
        "y_min": min(ys),
        "x_max": max(xs),
        "y_max": max(ys),
    }


def _extract_table_structure(result: Any) -> List[Dict[str, Any]]:
    tables_out: List[Dict[str, Any]] = []

    for table_idx, table in enumerate(getattr(result, "tables", []) or []):
        rows = getattr(table, "row_count", None) or 0
        cols = getattr(table, "column_count", None) or 0

        cells_by_row: List[List[Dict[str, Any]]] = [[] for _ in range(rows)] if rows else []

        cell_entries: List[Dict[str, Any]] = []
        for cell in getattr(table, "cells", []) or []:
            row_index = getattr(cell, "row_index", None)
            column_index = getattr(cell, "column_index", None)

            text = getattr(cell, "content", None)
            if text is None:
                text = getattr(cell, "text", None)

            cell_obj = {
                "row_index": row_index,
                "column_index": column_index,
                "row_span": getattr(cell, "row_span", None),
                "column_span": getattr(cell, "column_span", None),
                "is_header": bool(getattr(cell, "kind", None) == "columnHeader" or getattr(cell, "kind", None) == "rowHeader"),
                "content": text,
                "bounding_box": _polygon_to_bbox(getattr(cell, "polygon", None) or getattr(cell, "bounding_regions", None)),
            }
            cell_entries.append(cell_obj)

            if isinstance(row_index, int) and row_index >= 0:
                while len(cells_by_row) <= row_index:
                    cells_by_row.append([])
                cells_by_row[row_index].append(cell_obj)

        tables_out.append(
            {
                "table_index": table_idx,
                "row_count": rows,
                "column_count": cols,
                "cells": cell_entries,
                "rows": [
                    {
                        "row_index": idx,
                        "cells": sorted(row_cells, key=lambda c: (c["column_index"] if c["column_index"] is not None else 10**9)),
                    }
                    for idx, row_cells in enumerate(cells_by_row)
                ],
            }
        )

    return tables_out


def extract_table_cells_and_rows(document_path: str, model_id: str = "prebuilt-layout") -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(document_path, "rb") as f:
        poller = client.begin_analyze_document(model_id=model_id, body=f)
        result = poller.result()

    tables = _extract_table_structure(result)

    return {
        "content": getattr(result, "content", None),
        "tables": tables,
    }
